class RacesResource(_Resource):
    """Races & series. Motorsport and cycling, the sports /v2/sports marks with kind races, are organised in three levels. The smallest is the session: one timed part, which can be practice, qualifying, a sprint, the race itself or a stage of a cycling race. Sessions make up a race, which is a whole Grand Prix weekend or one cycling race, and races make up a series, the counterpart of a league elsewhere (Formula 1, MotoGP; in cycling, the complete men’s or women’s calendar). Live changes are pushed on the race:{id} WebSocket channel (Business plan and up); over REST the same three things, the race, its list of sessions and the results of one session, each have an endpoint of their own. Two conventions hold throughout: times are in milliseconds and distances in metres, and a driver, a rider or a team is a TeamRef, so /v2/teams/{id} returns its profile.
    """

    def calendar(self, *, sport: Literal["motorsport", "cycling"], month: str) -> t.RacesCalendarResponse:
        """Race calendar.

        Plans: free, starter, pro, business, enterprise.
        Docs: https://datasportsapi.com/docs/races/calendar/
        """
        return self._client._request("GET", "/v2/races/calendar", {"sport": sport, "month": month}, None)

    def list(self, *, sport: Literal["motorsport", "cycling"], date: str, tz: str | None = None) -> t.RacesListResponse:
        """Races.

        Plans: free, starter, pro, business, enterprise.
        Docs: https://datasportsapi.com/docs/races/list/
        """
        return self._client._request("GET", "/v2/races", {"sport": sport, "date": date, "tz": tz}, None)

    def get(self, id: int | str) -> t.RacesGetResponse:
        """Race.

        Plans: free, starter, pro, business, enterprise.
        Docs: https://datasportsapi.com/docs/races/get/
        """
        return self._client._request("GET", f"/v2/races/{_p(id)}", None, None)

    def sessions(self, id: int | str) -> t.RacesSessionsResponse:
        """Race sessions.

        Plans: free, starter, pro, business, enterprise.
        Docs: https://datasportsapi.com/docs/races/sessions/
        """
        return self._client._request("GET", f"/v2/races/{_p(id)}/sessions", None, None)

    def results(self, id: int | str, *, session: int | None = None) -> t.RacesResultsResponse:
        """Race results.

        Plans: free, starter, pro, business, enterprise.
        Docs: https://datasportsapi.com/docs/races/results/
        """
        return self._client._request("GET", f"/v2/races/{_p(id)}/results", {"session": session}, None)

    def laps(self, id: int | str, *, session: int | None = None) -> t.RacesLapsResponse:
        """Race laps.

        Plans: pro, business, enterprise.
        Docs: https://datasportsapi.com/docs/races/laps/
        """
        return self._client._request("GET", f"/v2/races/{_p(id)}/laps", {"session": session}, None)

    def odds(self, id: int | str) -> t.RacesOddsResponse:
        """Race odds.

        Plans: business, enterprise.
        Docs: https://datasportsapi.com/docs/races/odds/
        """
        return self._client._request("GET", f"/v2/races/{_p(id)}/odds", None, None)


