    async def list(self, *, sport: Literal["motorsport", "cycling"], date: str, tz: str | None = None) -> t.RacesListResponse:
        """Races.

        Plans: free, starter, pro, business, enterprise.
        Docs: https://datasportsapi.com/docs/races/list/
        """
        return await self._client._request("GET", "/v2/races", {"sport": sport, "date": date, "tz": tz}, None)

    async def get(self, id: int | str) -> t.RacesGetResponse:
        """Race.

        Plans: free, starter, pro, business, enterprise.
        Docs: https://datasportsapi.com/docs/races/get/
        """
        return await self._client._request("GET", f"/v2/races/{_p(id)}", None, None)

    async def sessions(self, id: int | str) -> t.RacesSessionsResponse:
        """Race sessions.

        Plans: free, starter, pro, business, enterprise.
        Docs: https://datasportsapi.com/docs/races/sessions/
        """
        return await self._client._request("GET", f"/v2/races/{_p(id)}/sessions", None, None)

